module book_circle (input clk, input rst_n, input start, input [3:0] boy_count, input [3:0] girl_count, input [7:0][7:0] adj_matrix, output reg [3:0] result, output reg done); reg [3:0] state; reg [3:0] current_boy; reg [7:0] current_mask; reg [2:0] current_girl; reg [3:0] best_value; reg [7:0] copy_counter; reg done_flag; reg [3:0] dp_curr [256]; reg [3:0] dp_next [256]; assign result = dp_curr[255]; always @(posedge clk) begin if (!rst_n) begin state <= 4'd0; current_boy <= 4'd0; current_mask <= 8'd0; current_girl <= 3'd0; best_value <= 4'd0; copy_counter <= 8'd0; done_flag <= 1'b0; end else begin case (state) 4'd0: if (start == 1 && !done_flag) state <= 4'd1; else state <=4'd0; done_flag <=1'b0; endcase 4'd1: state <=4'd2; done_flag <=1'b0; endcase 4'd2: if (current_boy < boy_count) begin state <=4'd3; current_mask <=8'd0; current_girl <=3'd0; best_value <=4'd0; end else begin state <=4'd9; done_flag <=1'b1; end endcase 4'd3: if (current_girl ==3'd0) best_value <= dp_curr[current_mask]; if (current_girl < girl_count) state <=4'd4; else begin dp_next[current_mask] <= best_value; state <=4'd6; current_mask <= current_mask +1; current_girl <=3'd0; best_value <=4'd0; end endcase 4'd4: if ((current_mask & (1 << current_girl)) && (adj_matrix[current_boy][current_girl] ==1)) begin int candidate; candidate = dp_curr[current_mask ^ (1 << current_girl)] +1; if (candidate > best_value) best_value <= candidate; end current_girl <= current_girl +1; state <=4'd3; endcase 4'd6: state <=4'd3; endcase 4'd7: if (copy_counter <256) begin dp_curr[copy_counter] <= dp_next[copy_counter]; copy_counter <= copy_counter +1; state <=4'd7; end else begin state <=4'd8; copy_counter <=8'd0; end done_flag <=1'b0; endcase 4'd8: current_boy <= current_boy +1; if (current_boy < boy_count) state <=4'd2; else begin state <=4'd9; done_flag <=1'b1; end endcase 4'd9: state <=4'd9; done_flag <=1'b1; endcase default: state <=4'd0; endcase end end assign done = done_flag; endmodule